+        email.addValueChangeListener(event -> onFieldEdited());
+        phone.addValueChangeListener(event -> onFieldEdited());
+        message.addValueChangeListener(event -> onFieldEdited());
+
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        messagesGrid.setItems(messageStore.getNewestFirst());
+        messagesGrid.setWidthFull();
+
+        add(heading, aboutLink, form, send, messagesGrid);
+    }
+
+    private void onFieldEdited() {
+        if (!resettingAfterSend) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void submit() {
+        clearValidation();
+
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        }
+        if (emailValue.isBlank() && phoneValue.isBlank()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), emailValue, phoneValue, messageValue));
+        messagesGrid.setItems(messageStore.getNewestFirst());
+        Notification.show("Message sent");
+
+        resettingAfterSend = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        resettingAfterSend = false;
+        send.setEnabled(false);
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        name.setErrorMessage(null);
+        email.setInvalid(false);
+        email.setErrorMessage(null);
+        message.setInvalid(false);
+        message.setErrorMessage(null);
+    }
+
+    private static void invalidate(HasValidation field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add(new Span("You have a message in progress. Discard it and leave?"));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+}
