+        assertTrue(send.isDisabled());
+        assertEquals("", page.getByLabel("Name").inputValue());
+        assertEquals("", page.getByLabel("Email").inputValue());
+        assertEquals("", page.getByLabel("Phone").inputValue());
+        assertEquals("", message.inputValue());
+        assertTrue(page.getByText("Browser user", new Page.GetByTextOptions().setExact(true)).isVisible());
