+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).waitFor();
+        page.navigate(getUrl() + "contact");
+        page.getByText("Contact", new Page.GetByTextOptions().setExact(true)).waitFor();
