+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validatesSendsAndKeepsMessagesAcrossNavigation() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertEquals("Name is required", name.getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue($(Grid.class).single().getDataProvider().size(new com.vaadin.flow.data.provider.Query<>()) == 0);
+
+        test(name).setValue("Alex");
+        test(email).setValue("not-an-email");
+        test(message).setValue("A first message");
+        test(send).click();
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+
+        test(email).clear();
+        test(phone).setValue("555-0101");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+
+        test(message).setValue("A first message");
+        fireShortcut(Key.ENTER);
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals(1, grid.getDataProvider().size(new com.vaadin.flow.data.provider.Query<>()));
+        assertEquals("Alex", grid.getDataProvider().fetch(new com.vaadin.flow.data.provider.Query<>()).findFirst().orElseThrow().name());
+        assertEquals("A first message", grid.getDataProvider().fetch(new com.vaadin.flow.data.provider.Query<>()).findFirst().orElseThrow().message());
+        assertFalse(send.isEnabled());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue($(Notification.class).all().stream()
+                .anyMatch(n -> n.getElement().getProperty("text").contains("Message sent")));
+
+        test(name).setValue("draft");
+        assertTrue(send.isEnabled());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertEquals(view, getCurrentView());
+        assertEquals("draft", name.getValue());
+
+        UI.getCurrent().navigate(AboutView.class);
+        test($(Button.class).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+
+        navigate(ContactView.class);
+        assertEquals(1, $(Grid.class).single().getDataProvider().size(new com.vaadin.flow.data.provider.Query<>()));
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Taylor");
+        test($(EmailField.class).withLabel("Email").single()).setValue("taylor@example.com");
+        test($(TextArea.class).withLabel("Message").single()).setValue("A newer message");
+        test($(Button.class).withText("Send").single()).click();
+        Grid<ContactMessage> updatedGrid = $(Grid.class).single();
+        assertEquals(2, updatedGrid.getDataProvider().size(new com.vaadin.flow.data.provider.Query<>()));
+        assertEquals("Taylor", updatedGrid.getDataProvider().fetch(new com.vaadin.flow.data.provider.Query<>())
+                .findFirst().orElseThrow().name());
+
+        // A freshly cleared form has nothing to confirm before leaving.
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertTrue($(Dialog.class).all().isEmpty());
+    }
